sys_variable_value.value:
(function execute(inputs, outputs) {

    var responseStr = inputs.response_body;
    var response = {};

    try {
        response = JSON.parse(responseStr);
    } catch (e) {
        outputs.translated_text = "Erro ao fazer parse do response: " + e.message;
        return;
    }

    if (response.translatedText) {
        outputs.translated_text = response.translatedText;
    } else {
        outputs.translated_text = "Translation not found or unexpected format.";
    }

})(inputs, outputs);

